import math
import numpy as np
import pytest
from app.wet_column import iapws_hydrogen_henry, wet_thermo, WetColumnInput
from app.calculations import calculate
from app.hydrogen import COMPONENTS
from app.reaction import gas_state, R


@pytest.mark.parametrize("temperature,tabulated",[(300,1.9702),(400,1.8464),(500,1.0513),(600,-.1848)])
def test_iapws_g7_04_published_table6(temperature,tabulated):
    # Published four-decimal values, not values generated by this implementation.
    assert math.log(iapws_hydrogen_henry(temperature)/1e9)==pytest.approx(tabulated,abs=5e-5)


@pytest.mark.parametrize("temperature",[273.14,636.10])
def test_iapws_rejects_outside_fitted_hydrogen_data_range(temperature):
    with pytest.raises(ValueError):iapws_hydrogen_henry(temperature)


def test_hot_wet_model_gibbs_duhem_and_enthalpy_temperature_derivative():
    model=wet_thermo(1.)
    t=360.;p=20000.;x=np.array([.001,.4,.5989999,1e-7])
    direction=np.array([.0002,-.03,.02980001,-1e-8])
    step=1e-4
    derivative=(model.phase(t,x+step*direction,p,True)[0]-model.phase(t,x-step*direction,p,True)[0])/(2*step)
    assert abs(float(x@derivative))<1e-7
    dt=.003
    temperature_derivative=(model.phase(t+dt,x,p,True)[0]-model.phase(t-dt,x,p,True)[0])/(2*dt)
    expected=sum(v*gas_state(name,t)[0] for name,v in zip(COMPONENTS,x))-R*t*t*float(x@temperature_derivative)
    assert model.phase(t,x,p,True)[2]==pytest.approx(expected,abs=.01)


def test_exact_properties_at_lower_condenser_boundary_do_not_extrapolate_psat():
    model=wet_thermo(1.)
    values,derivative=model.data(303.,True)
    assert np.isfinite(values).all() and np.isfinite(derivative).all()
    assert values[2]==pytest.approx(math.log(model.correlations.VaporPressures[2](303.)))
    with pytest.raises(ValueError):model.data(302.999,True)


@pytest.mark.parametrize("stages,feed_stage,reflux_ratio",[(6,3,3),(50,25,10)])
def test_wet_column_stage_balances_equilibrium_and_overhead_decanter(stages,feed_stage,reflux_ratio):
    r=calculate("wet_column",{"equilibrium_stages":stages,"feed_stage":feed_stage,"reflux_ratio":reflux_ratio})
    assert r["validation"]["passed"]
    model=wet_thermo(1.)
    outputs={s["outlet"]:s for s in r["outlets"]}
    d=outputs["organic_distillate"]
    reflux=r["reflux_flow_kmol_h"]
    stages=r["stages"]
    for i,name in enumerate(COMPONENTS):
        assert sum(s["component_flows_kmol_h"][name] for s in outputs.values())==pytest.approx(100*r["feed_mole_fractions"][i],abs=1e-7)
    for j,s in enumerate(stages):
        x=np.array(s["liquid_mole_fractions"]);y=np.array(s["vapor_mole_fractions"])
        logf,_,hl,hv=model.phase(s["temperature_K"],x,r["pressure_Pa"],True)
        assert np.exp(logf)==pytest.approx(y,abs=1e-8)
        incoming=np.zeros(4);h_in=0.
        lin=stages[j-1]["liquid_kmol_h"] if j else reflux
        xin=stages[j-1]["liquid_mole_fractions"] if j else d["mole_fractions"]
        hin=stages[j-1]["liquid_molar_enthalpy_J_mol"] if j else d["molar_enthalpy_J_mol"]
        incoming+=lin*np.array(xin);h_in+=lin*hin
        if j+1<len(stages):
            v=stages[j+1]
            incoming+=v["vapor_kmol_h"]*np.array(v["vapor_mole_fractions"])
            h_in+=v["vapor_kmol_h"]*v["vapor_molar_enthalpy_J_mol"]
        if s["feed"]:
            incoming+=100*np.array(r["feed_mole_fractions"])
            h_in+=100*r["feed_molar_enthalpy_J_mol"]
        outgoing=s["liquid_kmol_h"]*x+s["vapor_kmol_h"]*y
        assert outgoing==pytest.approx(incoming,abs=1e-7)
        assert np.max(abs(np.log(incoming/outgoing)))<1e-7
        q=3600*r["reboiler_duty_kW"] if j==len(stages)-1 else 0
        assert (h_in+q-s["liquid_kmol_h"]*hl-s["vapor_kmol_h"]*hv)/3600==pytest.approx(0,abs=1e-5)
    gas=np.array(outputs["vent"]["mole_fractions"])
    for name in ("organic_distillate","aqueous_distillate"):
        assert model.phase(r["condenser_temperature_K"],np.array(outputs[name]["mole_fractions"]),r["pressure_Pa"],True)[0]==pytest.approx(np.log(gas),abs=1e-7)
    overhead=stages[0]["vapor_kmol_h"]*np.array(stages[0]["vapor_mole_fractions"])
    recovered=sum((np.array([s["component_flows_kmol_h"][k] for k in COMPONENTS]) for s in r["outlets"] if s["outlet"]!="bottoms"),start=np.zeros(4))
    assert overhead==pytest.approx(recovered+reflux*np.array(d["mole_fractions"]),abs=1e-7)
    assert outputs["aqueous_distillate"]["flow_kmol_h"]>0 and outputs["vent"]["flow_kmol_h"]>0
    assert d["mole_fractions"][0]>0 and d["mole_fractions"][3]>0


def test_connected_train_transfers_wet_feed_and_actual_enthalpy_without_resetting():
    r=calculate("wet_separation_train",{"column_stages":6,"column_feed_stage":3})
    assert r["validation"]["passed"]
    feed=next(s for s in r["streams"] if s["id"]=="S05")
    col=r["column"]
    assert col["feed_kmol_h"]==pytest.approx(feed["total_kmol_h"])
    assert col["feed_kmol_h"]*col["feed_molar_enthalpy_J_mol"]/3600==pytest.approx(feed["enthalpy_flow_kW"],abs=1e-8)
    assert col["feed_mole_fractions"]==pytest.approx([feed["component_flows_kmol_h"][k]/feed["total_kmol_h"] for k in COMPONENTS])
    assert col["feed_mole_fractions"][0]>0 and col["feed_mole_fractions"][3]>0
    inlet=r["streams"][0];exits=[s for s in r["streams"] if s["boundary"]=="outlet"]
    assert len(exits)==6
    delta={"water":0,"ethylbenzene":-r["reaction_extent_kmol_h"],"styrene":r["reaction_extent_kmol_h"],"hydrogen":r["reaction_extent_kmol_h"]}
    for k in COMPONENTS:
        assert sum(s["component_flows_kmol_h"][k] for s in exits)==pytest.approx(inlet["component_flows_kmol_h"][k]+delta[k],abs=1e-6)
    assert sum(s["mass_kg_h"] for s in exits)==pytest.approx(inlet["mass_kg_h"],rel=1e-9)
    assert inlet["enthalpy_flow_kW"]+r["total_heat_input_kW"]-r["total_heat_removed_kW"]==pytest.approx(sum(s["enthalpy_flow_kW"] for s in exits),abs=1e-5)


@pytest.mark.parametrize("args",[{"pressure_Pa":9999},{"condenser_temperature_K":330},
    {"equilibrium_stages":6,"feed_stage":6},{"mole_fractions":[.02,.39,.59,0]}])
def test_wet_column_rejects_unsupported_input(args):
    with pytest.raises(ValueError):calculate("wet_column",args)


def test_wet_column_rejects_unstable_single_liquid_stages(monkeypatch):
    model=wet_thermo(1.)
    monkeypatch.setattr(model,"stability",lambda *args:-.1)
    with pytest.raises(ValueError,match="单液相不稳定"):
        calculate("wet_column",{"equilibrium_stages":6,"feed_stage":3})
